local function kick(func)
    game.Players.LocalPlayer:Kick("Incompatible Executor", func)
end

if not request then
    kick("request")
end

if not writefile then
    kick("writefile")
end

if not restorefunction then
    kick("restorefunction")
end

if not getgc then
    kick("getgc")
end

if not filtergc then
    kick("filtergc")
end

if not hookfunction then
    kick("hookfunction")
end

if not debug or not debug.setupvalue then
    kick("setupvalue")
end

if not debug.getstack then
    kick("getstack")
end
